class _ResponsiveFeedback(QgsProcessingFeedback):
    """
    Feedback personalizzato che chiama QApplication.processEvents() ad ogni
    aggiornamento di progresso, permettendo alla GUI di QGIS di rispondere
    durante le operazioni processing.run() lunghe (slope, aspect, rastersampling...).
    """
    def __init__(self, iface=None, step_label=""):
        super().__init__()
        self._iface = iface
        self._step_label = step_label

    def setProgress(self, progress):
        super().setProgress(progress)
        from qgis.PyQt.QtWidgets import QApplication
        QApplication.processEvents()

    def pushInfo(self, info):
        pass  # silenzia i log di processing per non intasare il pannello

    def reportError(self, error, fatalError=False):
        QgsMessageLog.logMessage(f"Processing error: {error}", "IPA", level=Qgis.Warning)


class RindexWorker(QObject):
    """
    Worker che esegue rindex_feas in un QThread separato,
    così la GUI di QGIS rimane completamente reattiva.
    I segnali aggiornano la progress bar nel thread principale.
    """
    # (valore 0-100, testo da mostrare)
    progress = pyqtSignal(int, str)
    finished = pyqtSignal()
    error = pyqtSignal(str)

    def __init__(self, ipa_instance):
        super().__init__()
        self._ipa = ipa_instance
        self._cancelled = False

    def cancel(self):
        self._cancelled = True

    def run(self):
        try:
            ipa = self._ipa
            has_polygon = ipa.dlg.comboBox_4.currentText() != ''

            # --- Step 1: Pendenza (0 → 20%) ---
            self.progress.emit(5, "Computing slope…")
            ipa.calcola_pendenza()
            if self._cancelled:
                return
            self.progress.emit(20, "Slope computed.")

            # --- Step 2: Esposizione (20 → 40%) ---
            self.progress.emit(25, "Computing aspect...")
            ipa.calcola_esposizione()
            if self._cancelled:
                return
            self.progress.emit(40, "Aspect computed.")

            # --- Step 3: LOS (40 → 55%) ---
            self.progress.emit(45, "Computing LOS…")
            ipa.calcolaLOS()
            if self._cancelled:
                return
            self.progress.emit(55, "LOS computed.")

            if ipa.errore == 1:
                # cleanup senza altri passi
                if has_polygon:
                    ipa.pulizia_layer(["Esposizione", "Pendenza", "Temp LOS", "Temp INC",
                                       "Slope_grad", "Aspect_grad", "Los_grad", "Inc_grad", "Rindex_totale"])
                else:
                    ipa.pulizia_layer(["Pendenza", "Esposizione", "Temp LOS", "Temp INC",
                                       "Slope_grad", "Aspect_grad", "Los_grad", "Inc_grad"])
                self.finished.emit()
                return

            # --- Step 4: addRaster_rindex (55 → 65%) ---
            self.progress.emit(58, "Generating angle rasters...")
            ipa.addRaster_rindex()
            if self._cancelled:
                return
            self.progress.emit(65, "Angle rasters ready.")

            # --- Step 5: converti_angoli (65 → 80%) ---
            self.progress.emit(68, "Converting angles to radians...")
            ipa.converti_angoli()
            if self._cancelled:
                return
            self.progress.emit(80, "Angles converted.")

            if ipa.esci != 0:
                # cleanup
                if has_polygon:
                    ipa.pulizia_layer(["Esposizione", "Pendenza", "Temp LOS", "Temp INC",
                                       "Slope_grad", "Aspect_grad", "Los_grad", "Inc_grad", "Rindex_totale"])
                else:
                    ipa.pulizia_layer(["Pendenza", "Esposizione", "Temp LOS", "Temp INC",
                                       "Slope_grad", "Aspect_grad", "Los_grad", "Inc_grad"])
                self.finished.emit()
                return

            # --- Step 6: Rindex_pixel / Rindex_pixel1 (80 → 95%) ---
            if has_polygon:
                self.progress.emit(83, "Computing reflection index (with polygon)…")
                ipa.Rindex_pixel()
                if self._cancelled:
                    return
                self.progress.emit(95, "GDI computed.")
                ipa.pulizia_layer(["Esposizione", "Pendenza", "Temp LOS", "Temp INC",
                                   "Slope_grad", "Aspect_grad", "Los_grad", "Inc_grad", "Rindex_totale"])
            else:
                self.progress.emit(83, "Computing reflection index...")
                ipa.Rindex_pixel1()
                if self._cancelled:
                    return
                self.progress.emit(95, "GDI computed.")
                ipa.pulizia_layer(["Pendenza", "Esposizione", "Temp LOS", "Temp INC",
                                   "Slope_grad", "Aspect_grad", "Los_grad", "Inc_grad"])

            self.progress.emit(100, "Processing complete.")
            self.finished.emit()

        except Exception as e:
            self.error.emit(str(e))


