class LsMaskWorker(QObject):
    """
    Worker che esegue calcolamask in un QThread separato,
    così la GUI di QGIS rimane completamente reattiva.
    """
    progress = pyqtSignal(int, str)
    finished = pyqtSignal()
    error = pyqtSignal(str)

    def __init__(self, ipa_instance):
        super().__init__()
        self._ipa = ipa_instance
        self._cancelled = False

    def cancel(self):
        self._cancelled = True

    def run(self):
        try:
            ipa = self._ipa

            self.progress.emit(5, "Starting LS mask computation...")

            import math
            import numpy as np
            from osgeo import gdal
            from qgis.core import QgsProject, QgsRasterLayer, QgsRasterBandStats, Qgis, QgsMapLayer

            # =========================================================
            # 1. Recupero del layer DEM
            # =========================================================
            selected_raster_layer_name = ipa.dlg.comboBox_17.currentText()
            raster_layers = QgsProject.instance().mapLayersByName(selected_raster_layer_name)

            if not raster_layers:
                self.error.emit("DEM layer not found.")
                return

            selected_raster_layer = raster_layers[0]
            if selected_raster_layer.type() != QgsMapLayer.RasterLayer:
                self.error.emit("DEM layer selected is not a raster layer.")
                return

            # Parametri DEM
            self.progress.emit(10, "Reading raster parameters...")
            provider = selected_raster_layer.dataProvider()
            extent = selected_raster_layer.extent()
            rows = selected_raster_layer.height()
            cols = selected_raster_layer.width()
            pixel_size = selected_raster_layer.rasterUnitsPerPixelX()

            # Lettura Array DEM
            self.progress.emit(15, "Reading DEM data...")
            block_dem = provider.block(1, extent, cols, rows)
            no_data_dem = provider.sourceNoDataValue(1)
            dem = np.frombuffer(block_dem.data(), dtype=np.float32).reshape((rows, cols)).copy()
            dem[dem == no_data_dem] = np.nan

            if self._cancelled:
                return

            # =========================================================
            # 2. Gestione Logica THETA (Raster o Costante)
            # =========================================================
            self.progress.emit(18, "Processing Theta angle...")
            
            theta_layer_name = ipa.dlg.comboBox_16.currentText() 
            
            if theta_layer_name != '':
                # --- CASO A: L'utente ha selezionato un RASTER ---
                theta_layers = QgsProject.instance().mapLayersByName(theta_layer_name)
                if not theta_layers:
                    self.error.emit("Theta layer not found.")
                    return
                theta_layer = theta_layers[0]
                
                theta_provider = theta_layer.dataProvider()
                block_theta = theta_provider.block(1, extent, cols, rows)
                no_data_theta = theta_provider.sourceNoDataValue(1)
                
                theta_array = np.frombuffer(block_theta.data(), dtype=np.float32).reshape((rows, cols)).copy()
                theta_array[theta_array == no_data_theta] = np.nan
                
                # Array 2D in radianti e minimo assoluto per il search range
                theta_rad_array = np.radians(theta_array)
                min_theta_rad = np.nanmin(theta_rad_array)
                
            else:
                # --- CASO B: ComboBox vuota, leggiamo la LineEdit (Valore Fisso) ---
                theta_text = ipa.dlg.lineEdit_17.text()
                if not theta_text:
                    self.error.emit("No Theta layer selected and no value entered.")
                    return
                try:
                    theta_val = float(theta_text)
                except ValueError:
                    self.error.emit("Invalid Theta value (must be a number).")
                    return
                
                theta_rad_val = np.radians(theta_val)
                # Creiamo una matrice 2D tutta uguale al valore inserito
                theta_rad_array = np.full_like(dem, theta_rad_val)
                min_theta_rad = theta_rad_val

            if self._cancelled:
                return

            # =========================================================
            # 3. Parametri per lo shifting
            # =========================================================
            self.progress.emit(20, "Computing search range...")
            stats = provider.bandStatistics(1, QgsRasterBandStats.All)
            delta_h_max = stats.maximumValue - stats.minimumValue

            # Calcolo del raggio d'azione basato sull'angolo più piccolo trovato
            max_search_dist_px = int(np.ceil((delta_h_max * np.tan(np.radians(90) - min_theta_rad)) / pixel_size))
            search_range = max(10, min(max_search_dist_px, 500))

            # Inizializzazione Maschera (0=Visibile, 1=Shadow, 2=Layover)
            ls_mask = np.zeros_like(dem, dtype=np.uint8)

            params = ipa.saved_parameters
            pass_mode = params.get('pass_mode', 'ASC')

            side_shadow = 1 if pass_mode == 'ASC' else -1
            side_layover = -1 if pass_mode == 'ASC' else 1

            if self._cancelled:
                return

            # =========================================================
            # 4. TEST SHADOW (1)
            # =========================================================
            self.progress.emit(25, "Computing shadow...")
            tan_theta_array = np.tan(theta_rad_array)
            
            for i in range(1, search_range):
                if self._cancelled:
                    return
                dist_m = i * pixel_size
                
                z_threshold = dem + (dist_m / tan_theta_array)
                dem_shifted = np.roll(dem, i * side_shadow, axis=1)
                ls_mask[(ls_mask == 0) & (dem_shifted > z_threshold)] = 1
                
                pct = 25 + int(35 * i / search_range)
                self.progress.emit(pct, f"Computing shadow... ({i}/{search_range})")

            if self._cancelled:
                return

            # =========================================================
            # 5. TEST LAYOVER (2)
            # =========================================================
            self.progress.emit(60, "Computing layover...")
            tan_layover_array = np.tan(np.radians(90) - theta_rad_array)
            
            for i in range(1, search_range):
                if self._cancelled:
                    return
                dist_m = i * pixel_size
                
                z_threshold_lay = dem + (dist_m / tan_layover_array)
                dem_shifted = np.roll(dem, i * side_layover, axis=1)
                ls_mask[(ls_mask == 0) & (dem_shifted > z_threshold_lay)] = 2
                
                pct = 60 + int(30 * i / search_range)
                self.progress.emit(pct, f"Computing layover... ({i}/{search_range})")

            if self._cancelled:
                return

            # =========================================================
            # 6. Salvataggio e Caricamento Risultato
            # =========================================================
            import tempfile
            import os
            
            self.progress.emit(92, "Saving temporary raster...")

            fd, output_path = tempfile.mkstemp(suffix=".tif", prefix="ls_mask_")
            os.close(fd) 

            driver = gdal.GetDriverByName('GTiff')
            out_ds = driver.Create(output_path, cols, rows, 1, gdal.GDT_Byte)

            out_ds.SetGeoTransform([
                extent.xMinimum(), pixel_size, 0,
                extent.yMaximum(), 0, -selected_raster_layer.rasterUnitsPerPixelY()
            ])
            out_ds.SetProjection(selected_raster_layer.crs().toWkt())

            out_ds.GetRasterBand(1).WriteArray(ls_mask)
            out_ds.FlushCache()
            out_ds = None

            # ---------------------------------------------------------
            # APPLICAZIONE SIMBOLOGIA PERSONALE (0=Good, 1=Shadow, 2=Layover)
            # ---------------------------------------------------------
            from qgis.core import QgsRasterLayer, QgsPalettedRasterRenderer
            from PyQt5.QtGui import QColor

            # Carichiamo temporaneamente il layer per applicargli lo stile
            temp_layer = QgsRasterLayer(output_path, f"LS_Mask_{pass_mode}")
            
            if temp_layer.isValid():
                # Definizione delle classi (Valore, Colore, Label)
                # Nota: Per lo 0 usiamo un colore totalmente trasparente QColor(0,0,0,0) come da screenshot
                classes = [
                    QgsPalettedRasterRenderer.Class(0, QColor(0, 0, 0, 0), "Good"),
                    QgsPalettedRasterRenderer.Class(1, QColor(255, 0, 0, 255), "Shadow"), # Rosso
                    QgsPalettedRasterRenderer.Class(2, QColor(255, 255, 0, 255), "Layover") # Giallo
                ]
                
                # Creazione del renderer Paletted/Unique Values
                renderer = QgsPalettedRasterRenderer(temp_layer.dataProvider(), 1, classes)
                temp_layer.setRenderer(renderer)
                
                # Salviamo lo stile all'interno del file .qml associato al raster
                # In questo modo, quando QGIS caricherà il file .tif, leggerà in automatico i colori
                style_path = output_path.replace(".tif", ".qml")
                temp_layer.saveNamedStyle(style_path)

            # ---------------------------------------------------------

            ipa._lsmask_output_path = output_path
            ipa._lsmask_pass_mode = pass_mode

            self.progress.emit(100, "Processing complete.")
            self.finished.emit()

        except Exception as e:
            self.error.emit(str(e))


class IsmTiffWorker(QObject):
    """
    Worker che esegue ism_tiff in un QThread separato,
    così la GUI di QGIS rimane completamente reattiva.
    """
    progress = pyqtSignal(int, str)
    finished = pyqtSignal()
    error = pyqtSignal(str)

    def __init__(self, ipa_instance):
        super().__init__()
        self._ipa = ipa_instance
        self._cancelled = False

    def cancel(self):
        self._cancelled = True

    def run(self):
        try:
            ipa = self._ipa

            self.progress.emit(5, "Computing slope (ISM)…")
            ipa.calcola_pendenzaism()
            if self._cancelled:
                return
            self.progress.emit(20, "Slope computed.")

            self.progress.emit(25, "Computing aspect (ISM)…")
            ipa.calcola_esposizioneism()
            if self._cancelled:
                return
            self.progress.emit(35, "Aspect computed.")

            self.progress.emit(40, "Computing LOS…")
            ipa.calcolaLOS5()
            if self._cancelled:
                return
            self.progress.emit(50, "LOS computed.")

            self.progress.emit(55, "Adding raster…")
            ipa.addRaster1()
            if self._cancelled:
                return
            self.progress.emit(65, "Raster added.")

            self.progress.emit(70, "Converting angles...")
            ipa.converti_angoli2()
            if self._cancelled:
                return
            self.progress.emit(78, "Angles converted.")

            self.progress.emit(80, "Computing Slope2LOS pixel…")
            ipa.Slope2Los_pixel2()
            if self._cancelled:
                return
            self.progress.emit(90, "Slope2LOS computed.")

            self.progress.emit(93, "Computing ISM…")
            ipa.calcolaISM()
            if self._cancelled:
                return
            self.progress.emit(97, "ISM computed.")

            ipa.pulizia_layer(["Pendenza", "Esposizione", "Temp LOS", "Slope_grad",
                                "Aspect_grad", "Los_grad", "Inc_grad", "Slope2LOS", "Temp INC"])

            self.progress.emit(100, "Processing complete.")
            self.finished.emit()

        except Exception as e:
            self.error.emit(str(e))


