    def density_mt(self):
        if not self.dlg.checkBox_9.isChecked():
            self.iface.messageBar().pushMessage("Error", "Please enter the orbital data", level=Qgis.Critical)
            return

        # ── Progress dialog ──────────────────────────────────────────────────
        self._densitymt_progress = QProgressDialog(
            "Starting Spatial Analysis processing...", "Cancel", 0, 100,
            self.iface.mainWindow()
        )
        self._densitymt_progress.setWindowTitle("Spatial Analysis")
        self._densitymt_progress.setMinimumWidth(400)
        self._densitymt_progress.setWindowModality(0)
        self._densitymt_progress.setMinimumDuration(0)
        self._densitymt_progress.setValue(0)
        self._densitymt_progress.show()
        QApplication.processEvents()

        try:
            # Step 1
            self._densitymt_progress.setLabelText("Computing slope...")
            self._densitymt_progress.setValue(5)
            QApplication.processEvents()
            self.calcola_pendenza_2()
            if self._densitymt_progress.wasCanceled(): return

            # Step 2
            self._densitymt_progress.setLabelText("Computing aspect...")
            self._densitymt_progress.setValue(25)
            QApplication.processEvents()
            self.calcola_esposizione_2()
            if self._densitymt_progress.wasCanceled(): return

            # Step 3
            self._densitymt_progress.setLabelText("Extracting slope pixel values...")
            self._densitymt_progress.setValue(42)
            QApplication.processEvents()
            self.estrai_valore_pixel_pendenza_2()
            if self._densitymt_progress.wasCanceled(): return

            # Step 4
            self._densitymt_progress.setLabelText("Slope extraction complete.")
            self._densitymt_progress.setValue(60)
            QApplication.processEvents()
            self.estrai_valore_pixel_esposizione_2()
            if self._densitymt_progress.wasCanceled(): return

            # Step 5
            self._densitymt_progress.setLabelText("Computing spatial analysis...")
            self._densitymt_progress.setValue(75)
            QApplication.processEvents()
            self.calcola_DensitaSpaziale2024new()
            if self._densitymt_progress.wasCanceled(): return

            # Step 6
            self._densitymt_progress.setLabelText("Cleaning up temporary layers..")
            self._densitymt_progress.setValue(95)
            QApplication.processEvents()
            self.pulizia_layer(["Pendenza", "Esposizione", "conSLOPE", "Count", "CountPixels",
                                "TEMPDENSITY", "temporary_points", "Slope_ritagliato",
                                "Aspect_ritagliato", "temp_layer", "Unito", "Slope_puntuale",
                                "Aspect_puntuale", "conEntrambi", "poligoni_ok"])

            # Conclusione
            self._densitymt_progress.setValue(100)
            self._densitymt_progress.close()
            
            self.imposta_stile_3() # se hai uno stile dedicato scommentalo
            self.iface.mapCanvas().refresh()

        except Exception as e:
            self._densitymt_progress.close()
            self.iface.messageBar().pushMessage(
                "Error", f"Error during Spatial Analysis computation: {str(e)}", level=Qgis.Critical
            )

