    def checksuipoligoni(self):
        # Recupera il layer poligonale
        polygon_layers = QgsProject.instance().mapLayersByName(self.dlg.comboBox_27.currentText())
        if not polygon_layers:
            self.iface.messageBar().pushWarning("Error", "Layer 'Polygons' not found.")
            return
        polygon_layer = polygon_layers[0]

        # Recupera il layer raster DEM
        dem_layers = QgsProject.instance().mapLayersByName(self.dlg.comboBox_25.currentText())
        if not dem_layers:
            self.iface.messageBar().pushWarning("Error", "Layer 'DEM' not found.")
            return
        dem_layer = dem_layers[0]
        dem_extent = dem_layer.extent()

        # Verifica: Poligoni dentro DEM
        poligoni_ok = []
        poligoni_fuori_dem = []

        for feature in polygon_layer.getFeatures():
            geom = feature.geometry()

            if dem_extent.contains(geom.boundingBox()):
                poligoni_ok.append(feature.id())
            else:
                poligoni_fuori_dem.append(feature.id())

        # Seleziona e mostra i poligoni fuori da DEM
        if poligoni_fuori_dem:
            polygon_layer.selectByIds(poligoni_fuori_dem)
            self.iface.messageBar().pushWarning(
                "DEM Check",
                f"{len(poligoni_fuori_dem)} polygons are NOT fully contained within the DEM."
            )
        else:
            self.iface.messageBar().pushInfo("DEM Check", "All polygons are contained within the DEM.")

        # Logging dei risultati
        QgsMessageLog.logMessage(f"Poligoni OK: {poligoni_ok}", "IPA", level=Qgis.Info)
        QgsMessageLog.logMessage(f"Poligoni out of DEM: {poligoni_fuori_dem}", "IPA", level=Qgis.Warning)

        return poligoni_ok, poligoni_fuori_dem

