    def save_parameters_3(self):
        # 1. ERROR CHECK: Are both boxes checked?
        if self.dlg.checkBox_5.isChecked() and self.dlg.checkBox_6.isChecked():
            self.iface.messageBar().pushMessage("Error", "Please select either ASC or DESC, not both!", level=Qgis.Critical)
            return

        # 2. ERROR CHECK: Are neither boxes checked?
        if not (self.dlg.checkBox_5.isChecked() or self.dlg.checkBox_6.isChecked()):
            self.iface.messageBar().pushMessage("Error", "You must select at least one orbit pass (ASC or DESC)!", level=Qgis.Critical)
            return

        # 3. Proceed if exactly one is checked.
        missione_selezionata = self.dlg.comboBox_12.currentText()
        
        if (all([self.dlg.lineEdit_14.text(), self.dlg.lineEdit_13.text(), self.dlg.lineEdit_15.text()])
            or missione_selezionata):
            
            parameters = {}
            parameters['pass_mode'] = "ASC" if self.dlg.checkBox_5.isChecked() else "DESC"
            
            if missione_selezionata in getattr(self, 'satellite_presets', {}):
                preset = self.satellite_presets[missione_selezionata]
                parameters['H_Sn'] = preset['H_Sn']
                parameters['orb_inclination'] = preset['orb_inclination']
                parameters['k'] = preset['k']
                parameters['lambda_set'] = preset['lambda_set']
            else:
                try:
                    parameters['H_Sn'] = float(self.dlg.lineEdit_14.text())
                    parameters['orb_inclination'] = float(self.dlg.lineEdit_13.text())
                    text = self.dlg.lineEdit_15.text().strip()
                    if "/" in text:
                        parts = text.replace(" ", "").split("/")
                        if len(parts) == 2:
                            parameters['k'] = float(parts[0]) / float(parts[1])
                        else:
                            self.iface.messageBar().pushMessage("Error", "Invalid format for k. Use 'numerator/denominator'.", level=Qgis.Critical)
                            return
                    else:
                        parameters['k'] = float(text)
                except ValueError:
                    self.iface.messageBar().pushMessage("Error", "Invalid value for orbital parameters!", level=Qgis.Critical)
                    return

            self.saved_parameters = parameters
            self.iface.messageBar().pushMessage("Success", "Data saved successfully!", level=Qgis.Success)
            self.dlg.checkBox_9.setCheckable(True)
            self.dlg.checkBox_9.setChecked(True)
        else:
            self.iface.messageBar().pushMessage("Error", "Please fill in all the text fields or select a satellite from the drop-down menu!", level=Qgis.Critical)

    def phase_tiff(self):
        if not self.dlg.checkBox_8.isChecked():
            self.iface.messageBar().pushMessage("Error", "Enter the orbital data", level=Qgis.Critical)
            return
        self.calcola_pendenzaphase()
        self.calcola_esposizionephase()
        self.calcolaLOSphase()
        self.addRasterphase()
        self.converti_angoliphase()
        self.Slope2Los_pixel2()
        self.calcolaPHASE()
        self.pulizia_layer(["Pendenza", "Esposizione", "Temp LOS", "Slope_grad", "Aspect_grad", "Los_grad", "Inc_grad", "Slope2LOS", "Temp INC"])

    def ism_tiff(self):
        if not self.dlg.checkBox_8.isChecked():
            self.iface.messageBar().pushMessage("Error", "Enter the orbital data", level=Qgis.Critical)
            return

        # ── Progress dialog ──────────────────────────────────────────────────
        self._ismtiff_progress = QProgressDialog(
            "Starting ISM processing...", "Cancel", 0, 100,
            self.iface.mainWindow()
        )
        self._ismtiff_progress.setWindowTitle("ISM")
        self._ismtiff_progress.setMinimumWidth(400)
        self._ismtiff_progress.setWindowModality(0)
        self._ismtiff_progress.setMinimumDuration(0)
        self._ismtiff_progress.setValue(0)
        self._ismtiff_progress.show()
        QApplication.processEvents()

        # ── Worker + Thread ──────────────────────────────────────────────────
        self._ismtiff_thread = QThread()
        self._ismtiff_worker = IsmTiffWorker(self)
        self._ismtiff_worker.moveToThread(self._ismtiff_thread)

        self._ismtiff_thread.started.connect(self._ismtiff_worker.run)
        self._ismtiff_worker.progress.connect(self._on_ismtiff_progress)
        self._ismtiff_worker.finished.connect(self._on_ismtiff_finished)
        self._ismtiff_worker.error.connect(self._on_ismtiff_error)
        self._ismtiff_progress.canceled.connect(self._ismtiff_worker.cancel)

        self._ismtiff_thread.start()

    def _on_ismtiff_progress(self, value, label):
        if self._ismtiff_progress:
            self._ismtiff_progress.setValue(value)
            self._ismtiff_progress.setLabelText(label)
        QApplication.processEvents()

    def _on_ismtiff_finished(self):
        self._ismtiff_thread.quit()
        self._ismtiff_thread.wait()
        if self._ismtiff_progress:
            self._ismtiff_progress.setValue(100)
            self._ismtiff_progress.close()
        self.iface.messageBar().pushMessage(
            "IPA", "ISM processing complete.", level=Qgis.Success
        )
        self.iface.mapCanvas().refresh()

    def _on_ismtiff_error(self, msg):
        self._ismtiff_thread.quit()
        self._ismtiff_thread.wait()
        if self._ismtiff_progress:
            self._ismtiff_progress.close()
        self.iface.messageBar().pushMessage(
            "Error", f"Error during ISM computation: {msg}", level=Qgis.Critical
        )

