    def lsmask(self):
        if not self.dlg.checkBox_7.isChecked():
            self.iface.messageBar().pushMessage("Error", "Enter the orbital data", level=Qgis.Critical)
            return

        # ── Rimozione layer LS_Mask precedente dal progetto (thread principale) ──
        # Deve avvenire qui, prima del thread, perché le API QGIS non sono thread-safe.
        # Questo sblocca il file .tif così il worker può sovrascriverlo senza "Permission denied".
        params = getattr(self, 'saved_parameters', {})
        pass_mode_preview = params.get('pass_mode', 'ASC')
        expected_layer_name = f"LS_Mask_{pass_mode_preview}"
        layers_to_remove = [
            layer for layer in QgsProject.instance().mapLayers().values()
            if layer.name() == expected_layer_name
        ]
        for layer in layers_to_remove:
            QgsProject.instance().removeMapLayer(layer.id())
        QApplication.processEvents()

        # ── Progress dialog ──────────────────────────────────────────────────
        self._lsmask_progress = QProgressDialog(
            "Starting LS Mask processing...", "Cancel", 0, 100,
            self.iface.mainWindow()
        )
        self._lsmask_progress.setWindowTitle("LS Mask")
        self._lsmask_progress.setMinimumWidth(400)
        self._lsmask_progress.setWindowModality(0)   # NonModal: QGIS resta usabile
        self._lsmask_progress.setMinimumDuration(0)  # mostra subito
        self._lsmask_progress.setValue(0)
        self._lsmask_progress.show()
        QApplication.processEvents()

        # ── Worker + Thread ──────────────────────────────────────────────────
        self._lsmask_thread = QThread()
        self._lsmask_worker = LsMaskWorker(self)
        self._lsmask_worker.moveToThread(self._lsmask_thread)

        # Connessioni segnali
        self._lsmask_thread.started.connect(self._lsmask_worker.run)
        self._lsmask_worker.progress.connect(self._on_lsmask_progress)
        self._lsmask_worker.finished.connect(self._on_lsmask_finished)
        self._lsmask_worker.error.connect(self._on_lsmask_error)
        self._lsmask_progress.canceled.connect(self._lsmask_worker.cancel)

        self._lsmask_thread.start()

    def _on_lsmask_progress(self, value, label):
        """Aggiorna la progress bar dal thread principale."""
        if self._lsmask_progress:
            self._lsmask_progress.setValue(value)
            self._lsmask_progress.setLabelText(label)
        QApplication.processEvents()

    def _on_lsmask_finished(self):
        """Chiamato quando il worker termina con successo."""
        self._lsmask_thread.quit()
        self._lsmask_thread.wait()
        if self._lsmask_progress:
            self._lsmask_progress.setValue(100)
            self._lsmask_progress.close()
        # Caricamento in QGIS dal thread principale
        from qgis.core import QgsRasterLayer, QgsProject
        new_layer = QgsRasterLayer(self._lsmask_output_path, f"LS_Mask_{self._lsmask_pass_mode}")
        QgsProject.instance().addMapLayer(new_layer)
        self.iface.messageBar().pushMessage(
            "Success", f"Mask {self._lsmask_pass_mode} successfully generated.", level=Qgis.Info
        )
        self.iface.mapCanvas().refresh()

