    def save_parameters(self):
        # 1. ERROR CHECK: Are both boxes checked?
        if self.dlg.checkBox.isChecked() and self.dlg.checkBox_2.isChecked():
            self.iface.messageBar().pushMessage("Error", "Please select either ASC or DESC, not both!", level=Qgis.Critical)
            return

        # 2. ERROR CHECK: Are neither boxes checked?
        if not (self.dlg.checkBox.isChecked() or self.dlg.checkBox_2.isChecked()):
            self.iface.messageBar().pushMessage("Error", "You must select at least one orbit pass (ASC or DESC)!", level=Qgis.Critical)
            return

        # 3. Proceed if exactly one is checked.
        missione_selezionata = self.dlg.comboBox.currentText()
        
        if (all([self.dlg.lineEdit.text(), self.dlg.lineEdit_2.text(), self.dlg.lineEdit_3.text()])
            or missione_selezionata):
            
            parameters = {}
            parameters['pass_mode'] = "ASC" if self.dlg.checkBox.isChecked() else "DESC"
            
            if missione_selezionata in getattr(self, 'satellite_presets', {}):
                preset = self.satellite_presets[missione_selezionata]
                parameters['H_Sn'] = preset['H_Sn']
                parameters['orb_inclination'] = preset['orb_inclination']
                parameters['k'] = preset['k']
                parameters['lambda_set'] = preset['lambda_set']
            else:
                try:
                    parameters['H_Sn'] = float(self.dlg.lineEdit.text())
                    parameters['orb_inclination'] = float(self.dlg.lineEdit_2.text())
                    text = self.dlg.lineEdit_3.text().strip()
                    if "/" in text:
                        parts = text.replace(" ", "").split("/")
                        if len(parts) == 2:
                            parameters['k'] = float(parts[0]) / float(parts[1])
                        else:
                            self.iface.messageBar().pushMessage("Error", "Invalid format for k. Use 'numerator/denominator'.", level=Qgis.Critical)
                            return
                    else:
                        parameters['k'] = float(text)
                except ValueError:
                    self.iface.messageBar().pushMessage("Error", "Invalid value for orbital parameters!", level=Qgis.Critical)
                    return

            self.saved_parameters = parameters
            self.iface.messageBar().pushMessage("Success", "Data saved successfully!", level=Qgis.Success)
            self.dlg.checkBox_7.setCheckable(True)
            self.dlg.checkBox_7.setChecked(True)
        else:
            self.iface.messageBar().pushMessage("Error", "Please fill in all the text fields or select a satellite from the drop-down menu!", level=Qgis.Critical)

    def populate_layer_combobox(self, comboBox, layer_type):
        layers = QgsProject.instance().mapLayers().values()
        for layer in layers:
            if layer.type() == layer_type:
                comboBox.addItem(layer.name())
    
    def populate_polygon_layer_combobox(self, comboBox):
        layers = QgsProject.instance().mapLayers().values()
        
        for layer in layers:
            if isinstance(layer, QgsVectorLayer) and layer.geometryType() == QgsWkbTypes.PolygonGeometry:
                comboBox.addItem(layer.name())

