        self.dlg.comboBox_23.addItem('')
        self.dlg.comboBox_26.addItem('')
        self.dlg.comboBox_datelayer.addItem('')
        self.dlg.comboBox_vel.addItem('')
        self.dlg.comboBox_ID.addItem('')
