                 # controlli aggiunti per errore prof
                denom = math.cos(Lat_m_rad)**2 - math.cos(orb_inclination_rad)**2
                if denom < 0:
                    self.iface.messageBar().pushMessage("Error during calculation: the value under the square root is negative.", level=Qgis.Critical)
                    return

                # Calcolo di heading ang
                heading_S = math.degrees(math.atan((math.cos(orb_inclination_rad) - (math.cos(Lat_m_rad) ** 2) / k) / 
                                math.sqrt(math.cos(Lat_m_rad) ** 2 - math.cos(orb_inclination_rad) ** 2)))

                # Modifica se la modalità è discendente
                if pass_mode == "DESC":
                    heading_S = 180 - heading_S

                # Calcolo di dheading
                Re = 6371000
                dheading = (H_Sn / Re) * math.tan(inc_ang_m_rad) * math.cos(math.radians(heading_S)) * math.tan(Lat_m_rad)

                # Calcolo di heading_angle
