    def converti_angoli(self):
        if self.dlg.comboBox_3.currentText() != '':
            # Ottieni il layer raster utilizzando il nome
            slope_layers = QgsProject.instance().mapLayersByName('Pendenza')
            aspect_layers = QgsProject.instance().mapLayersByName('Esposizione')
            los_layers = QgsProject.instance().mapLayersByName('Temp LOS')
            name_inc_layer = self.dlg.comboBox_3.currentText()
            inc_layers = QgsProject.instance().mapLayersByName(name_inc_layer)

            self.esci = 0
            if not los_layers:
                self.esci = 1
                return
            
            slope_layer = slope_layers[0]
            aspect_layer = aspect_layers[0]
            los_layer = los_layers[0]
            inc_layer = inc_layers[0]

            result = processing.run("native:rastercalc", {
            'LAYERS' : slope_layer,
            'EXPRESSION': '"Pendenza@1"  * 3.141592654  / 180',
            'EXTENT': None,
            'CELL_SIZE': None,
            'CRS': None,
            'OUTPUT': 'TEMPORARY_OUTPUT'
            })
            
            raster_file = result['OUTPUT']
            raster_layer = QgsRasterLayer(raster_file, "Slope_grad")
            QgsProject.instance().addMapLayer(raster_layer)

            result = processing.run("native:rastercalc", {
            'LAYERS' : aspect_layer,
            'EXPRESSION': '"Esposizione@1"  * 3.141592654  / 180',
            'EXTENT': None,
            'CELL_SIZE': None,
            'CRS': None,
            'OUTPUT': 'TEMPORARY_OUTPUT'
            })
            
            raster_file = result['OUTPUT']
            raster_layer = QgsRasterLayer(raster_file, "Aspect_grad")
            QgsProject.instance().addMapLayer(raster_layer)

            result = processing.run("native:rastercalc", {
            'LAYERS' : los_layer,
            'EXPRESSION': '"Temp LOS@1"  * 3.141592654  / 180',
            'EXTENT': None,
            'CELL_SIZE': None,
            'CRS': None,
            'OUTPUT': 'TEMPORARY_OUTPUT'
            })
            
            raster_file = result['OUTPUT']
            raster_layer = QgsRasterLayer(raster_file, "Los_grad")
            QgsProject.instance().addMapLayer(raster_layer)

            result = processing.run("native:rastercalc", {
            'LAYERS' : inc_layer,
            'EXPRESSION': f'"{name_inc_layer}@1"  * 3.141592654  / 180',
            'EXTENT': None,
            'CELL_SIZE': None,
            'CRS': None,
            'OUTPUT': 'TEMPORARY_OUTPUT'
            })
            
            raster_file = result['OUTPUT']
            raster_layer = QgsRasterLayer(raster_file, "Inc_grad")
            QgsProject.instance().addMapLayer(raster_layer)

        else:
            # Ottieni il layer raster utilizzando il nome
            slope_layers = QgsProject.instance().mapLayersByName('Pendenza')
            aspect_layers = QgsProject.instance().mapLayersByName('Esposizione')
            los_layers = QgsProject.instance().mapLayersByName('Temp LOS')
