    def Slope2Los_pixel(self):
        slope_layers = QgsProject.instance().mapLayersByName('Slope_grad')
        aspect_layers = QgsProject.instance().mapLayersByName('Aspect_grad')
        los_layers = QgsProject.instance().mapLayersByName('Los_grad')
        inc_layers = QgsProject.instance().mapLayersByName('Inc_grad')

        slope_layer = slope_layers[0]
        aspect_layer = aspect_layers[0]
        los_layer = los_layers[0]
        inc_layer = inc_layers[0]

        if self.dlg.lineEdit_6.text():
            soglia = float(self.dlg.lineEdit_6.text())
            soglia_rad = soglia * math.pi / 180
            expression = (
                'if("Slope_grad@1" >= {soglia_rad}, '
            '    ( sin("Slope_grad@1")*cos("Inc_grad@1") ) + '
            '    ( cos("Slope_grad@1")*sin("Inc_grad@1")*cos( ("Los_grad@1" - 3.141592654 + 1.5707963) - "Aspect_grad@1" ) ), '
            '    -9999'
            ')'
            ).format(soglia_rad=soglia_rad)

            if self.dlg.comboBox_7.currentText():
                ritaglio = QgsProject.instance().mapLayersByName(self.dlg.comboBox_7.currentText())[0]
                extent_raster = ritaglio.extent()
            else:
                ritaglio = QgsProject.instance().mapLayersByName(self.dlg.comboBox_6.currentText())[0]
                extent_raster = ritaglio.extent()
            
            result = processing.run("native:rastercalc", {
                    'LAYERS' : [slope_layer, aspect_layer, los_layer, inc_layer],
                    'EXPRESSION': expression,
                    'EXTENT': extent_raster,
                    'CELL_SIZE': None,
                    'CRS': None,
                    'OUTPUT': 'TEMPORARY_OUTPUT'
                })
            raster_file = result['OUTPUT']
            raster_layer = QgsRasterLayer(raster_file, "Slope2LOS")

            provider = raster_layer.dataProvider()
            no_data_range = QgsRasterRange(-9999, -9999)
            provider.setUserNoDataValue(1, [no_data_range])

            QgsProject.instance().addMapLayer(raster_layer)
            renderer = QgsSingleBandGrayRenderer(provider, 1)

            stats = provider.bandStatistics(1, QgsRasterBandStats.All)
            min_val = stats.minimumValue
            max_val = stats.maximumValue

            contrast_enhancement = QgsContrastEnhancement(provider.dataType(1))
            contrast_enhancement.setContrastEnhancementAlgorithm(QgsContrastEnhancement.StretchToMinimumMaximum, True)
            contrast_enhancement.setMinimumValue(min_val)
            contrast_enhancement.setMaximumValue(max_val)
                
            renderer.setContrastEnhancement(contrast_enhancement)
            raster_layer.setRenderer(renderer)
            raster_layer.triggerRepaint()

            '''renderer = QgsSingleBandGrayRenderer(provider, 1)

            stats = provider.bandStatistics(1, QgsRasterBandStats.All)
            min_val = stats.minimumValue
            max_val = stats.maximumValue

            contrast_enhancement = QgsContrastEnhancement(provider.dataType(1))
            contrast_enhancement.setContrastEnhancementAlgorithm(QgsContrastEnhancement.StretchToMinimumMaximum, True)
            contrast_enhancement.setMinimumValue(min_val)
            contrast_enhancement.setMaximumValue(max_val)
            
            renderer.setContrastEnhancement(contrast_enhancement)
            raster_layer.setRenderer(renderer)'''
            # Costruisci un renderer nuovo che tenga conto del NoData
            #renderer = raster_layer.renderer().clone()
            #renderer.setRasterTransparency(raster_layer.renderer().rasterTransparency())

            #raster_layer.setRenderer(renderer)
            #raster_layer.triggerRepaint()
            
        else:
            ritaglio = QgsProject.instance().mapLayersByName(self.dlg.comboBox_6.currentText())[0]
            extent_raster = ritaglio.extent()
            
            result = processing.run("native:rastercalc", {
                'LAYERS' : [slope_layer, aspect_layer, los_layer, inc_layer],
                'EXPRESSION': '( sin ( "Slope_grad@1")* cos ( "Inc_grad@1"))+( cos ( "Slope_grad@1")* sin ( "Inc_grad@1")* cos ( ("Los_grad@1"-3.141592654+1.5707963)-"Aspect_grad@1"))',
                'EXTENT': extent_raster,
                'CELL_SIZE': None,
                'CRS': None,
                'OUTPUT': 'TEMPORARY_OUTPUT'
            })  
            raster_file = result['OUTPUT']
            raster_layer = QgsRasterLayer(raster_file, "Slope2LOS")
            QgsProject.instance().addMapLayer(raster_layer)

    def Slope2Los_pixel1(self):
        slope_layers = QgsProject.instance().mapLayersByName('Slope_grad')
        aspect_layers = QgsProject.instance().mapLayersByName('Aspect_grad')
        los_layers = QgsProject.instance().mapLayersByName('Los_grad')
        inc_layers = QgsProject.instance().mapLayersByName('Inc_grad')

        slope_layer = slope_layers[0]
        aspect_layer = aspect_layers[0]
        los_layer = los_layers[0]
        inc_layer = inc_layers[0]
        
        polygon_layers = QgsProject.instance().mapLayersByName(self.dlg.comboBox_5.currentText())
        polygon_layer = polygon_layers[0]
        extent = polygon_layer.extent()
    
        if self.dlg.lineEdit_6.text():
                soglia = float(self.dlg.lineEdit_6.text())
                soglia_rad = soglia * math.pi / 180
                expression = (
                    'if("Slope_grad@1" >= {soglia_rad}, '
                '    ( sin("Slope_grad@1")*cos("Inc_grad@1") ) + '
                '    ( cos("Slope_grad@1")*sin("Inc_grad@1")*cos( ("Los_grad@1" - 3.141592654 + 1.5707963) - "Aspect_grad@1" ) ), '
                '    -9999'
                ')'
                ).format(soglia_rad=soglia_rad)

                result = processing.run("native:rastercalc", {
                    'LAYERS' : [slope_layer, aspect_layer, los_layer, inc_layer],
                    'EXPRESSION': expression,
                    'EXTENT': extent,
                    'CELL_SIZE': None,
                    'CRS': polygon_layer.crs(),
                    'OUTPUT': 'TEMPORARY_OUTPUT'
                })
                raster_file = result['OUTPUT']
                raster_layer = QgsRasterLayer(raster_file, "Slope2LOS_nonclip")

                QgsProject.instance().addMapLayer(raster_layer)

        else:
            result = processing.run("native:rastercalc", {
                'LAYERS' : [slope_layer, aspect_layer, los_layer, inc_layer],
                'EXPRESSION': '( sin ( "Slope_grad@1")* cos ( "Inc_grad@1"))+( cos ( "Slope_grad@1")* sin ( "Inc_grad@1")* cos ( ("Los_grad@1"-3.141592654+1.5707963)-"Aspect_grad@1"))',
                'EXTENT': extent,
                'CELL_SIZE': None,
                'CRS': polygon_layer.crs(),
                'OUTPUT': 'TEMPORARY_OUTPUT'
            })
            raster_file = result['OUTPUT']
            raster_layer = QgsRasterLayer(raster_file, "Slope2LOS_nonclip")
            QgsProject.instance().addMapLayer(raster_layer)

        selected_poligon_layer_name = self.dlg.comboBox_5.currentText() 
        poligono_layers = QgsProject.instance().mapLayersByName(selected_poligon_layer_name)
        poligono_layer = poligono_layers[0]

        # Definisci i parametri per l'algoritmo di ritaglio
        parameters = {
        'INPUT': raster_layer.source(),
        'MASK': poligono_layer.source(),
        'TARGET_CRS': raster_layer.crs(),
        'NODATA': None,
        'ALPHA_BAND': False,
        'CROP_TO_CUTLINE': True,
        'KEEP_RESOLUTION': True,
        'OUTPUT': 'TEMPORARY_OUTPUT'
        }
                
        # Esegui l'algoritmo di ritaglio
        feedback = QgsProcessingFeedback()
        result = processing.run("gdal:cliprasterbymasklayer", parameters, feedback=feedback)

        # Ottieni il risultato
        clipped_raster = result['OUTPUT']
        clippe_layer = QgsRasterLayer(clipped_raster, "Slope2LOS")

        # Aggiungi il raster ritagliato al progetto
        #QgsProject.instance().addMapLayer(clippe_layer)

        '''expression = "({0}@1 < -9999) * -9999 + ({0}@1 >= -9999) * {0}@1".format(clippe_layer.name())
        result = processing.run("native:rastercalc", {
        'LAYERS' : [clippe_layer],
        'EXPRESSION': expression,
        'EXTENT': None,
        'CELL_SIZE': None,
        'CRS': None,
        'OUTPUT': 'TEMPORARY_OUTPUT'
        })
        clippe_layer = result['OUTPUT']
        clippe_layer = QgsRasterLayer(clippe_layer, "Slope2Los_clip")'''

        provider = clippe_layer.dataProvider()  
        no_data_range = [QgsRasterRange(-9999, -9999)]
        provider.setUserNoDataValue(1, no_data_range)

        renderer = QgsSingleBandGrayRenderer(provider, 1)

        stats = provider.bandStatistics(1, QgsRasterBandStats.All)
        min_val = stats.minimumValue
        max_val = stats.maximumValue

        contrast_enhancement = QgsContrastEnhancement(provider.dataType(1))
        contrast_enhancement.setContrastEnhancementAlgorithm(QgsContrastEnhancement.StretchToMinimumMaximum, True)
        contrast_enhancement.setMinimumValue(min_val)
        contrast_enhancement.setMaximumValue(max_val)
            
        renderer.setContrastEnhancement(contrast_enhancement)
        clippe_layer.setRenderer(renderer)
        clippe_layer.triggerRepaint()

        QgsProject.instance().addMapLayer(clippe_layer)

    def Rindex_pixel1(self):
        slope_layers = QgsProject.instance().mapLayersByName('Slope_grad')
        aspect_layers = QgsProject.instance().mapLayersByName('Aspect_grad')
        los_layers = QgsProject.instance().mapLayersByName('Los_grad')
        inc_layers = QgsProject.instance().mapLayersByName('Inc_grad')

        if not los_layers:
            return
    
        if not inc_layers:
            return

        slope_layer = slope_layers[0]
        aspect_layer = aspect_layers[0]
        los_layer = los_layers[0]
        inc_layer = inc_layers[0]

        if self.dlg.comboBox_3.currentText() != '':
            ritaglio = QgsProject.instance().mapLayersByName(self.dlg.comboBox_3.currentText())[0]
        else:
            ritaglio = QgsProject.instance().mapLayersByName(self.dlg.comboBox_2.currentText())[0]
        extent_raster = ritaglio.extent()

        result = processing.run("native:rastercalc", {
        'LAYERS' : [slope_layer, aspect_layer, los_layer, inc_layer],
        'EXPRESSION': 'sin ("Inc_grad@1") * cos ("Slope_grad@1") + cos("Inc_grad@1") * sin ("Slope_grad@1") * cos ("Los_grad@1"-"Aspect_grad@1" - 1.5707963)',
        'EXTENT': extent_raster,
        'CELL_SIZE': None,
        'CRS': None,
        'OUTPUT': 'TEMPORARY_OUTPUT'
        })
        raster_file = result['OUTPUT']
        raster_layer = QgsRasterLayer(raster_file, "GDI")
        QgsProject.instance().addMapLayer(raster_layer)


    def Rindex_pixel(self):
        from qgis.core import QgsProject, QgsRasterLayer, QgsProcessingUtils
        import processing

        # 1. Acquisizione dei layer di base
        slope_layers = QgsProject.instance().mapLayersByName('Slope_grad')
        aspect_layers = QgsProject.instance().mapLayersByName('Aspect_grad')
        los_layers = QgsProject.instance().mapLayersByName('Los_grad')
        inc_layers = QgsProject.instance().mapLayersByName('Inc_grad')

        if not los_layers or not inc_layers or not slope_layers or not aspect_layers:
            return

        slope_layer = slope_layers[0]
        aspect_layer = aspect_layers[0]
        los_layer = los_layers[0]
        inc_layer = inc_layers[0]

        # 2. Esecuzione del rastercalc
        result_calc = processing.run("native:rastercalc", {
            'LAYERS' : [slope_layer, aspect_layer, los_layer, inc_layer],
            'EXPRESSION': 'sin ("Inc_grad@1") * cos ("Slope_grad@1") + cos("Inc_grad@1") * sin ("Slope_grad@1") * cos ("Los_grad@1"-"Aspect_grad@1" - 1.5707963)',
            'EXTENT': None,
            'CELL_SIZE': None,
            'CRS': los_layer.crs(),
            'OUTPUT': 'TEMPORARY_OUTPUT'
        })
        
        # Recuperiamo il percorso fisico del file originato dal rastercalc
        calc_raster_file = result_calc['OUTPUT']
        
        # Creiamo e aggiungiamo il primo layer (Rindex_totale)
        rindex_layer = QgsRasterLayer(calc_raster_file, "Rindex_totale")
        QgsProject.instance().addMapLayer(rindex_layer)
        
        # 3. Acquisizione del poligono di taglio
        selected_poligon_layer_name = self.dlg.comboBox_4.currentText() 
        poligono_layers = QgsProject.instance().mapLayersByName(selected_poligon_layer_name)
        
        if not poligono_layers:
            return
            
        poligono_layer = poligono_layers[0]

        # 4. Preparazione e avvio del taglio con GDAL
        # Estraiamo la STRINGA del Sistema di Riferimento (es. "EPSG:32632") necessaria per GDAL
        crs_auth_id = poligono_layer.crs().authid()

        # Generiamo un nome temporaneo univoco per evitare file lock
        gdal_output_path = QgsProcessingUtils.generateTempFilename('gdi_clipped.tif')

        result_clip = processing.run("gdal:cliprasterbymasklayer", {
            'INPUT': calc_raster_file,
            'MASK': poligono_layer,
            'SOURCE_CRS': crs_auth_id,
            'TARGET_CRS': crs_auth_id, 
            'TARGET_EXTENT': None,
            'NODATA': None,
            'ALPHA_BAND': False, 
            'CROP_TO_CUTLINE': True,
            'KEEP_RESOLUTION': False,
            'SET_RESOLUTION': False, 
            'X_RESOLUTION': None,
            'Y_RESOLUTION': None,
            'MULTITHREADING': False,
            'OPTIONS': '',
            'DATA_TYPE': 0,
            'EXTRA': '',  # Lasciato rigorosamente vuoto per non generare errori con gdalwarp
            'OUTPUT': gdal_output_path
        })
        
        clipped_raster_file = result_clip['OUTPUT']
        
        # 5. Caricamento del risultato
        clipped_layer = QgsRasterLayer(clipped_raster_file, "GDI")
        
        # Verifica ed inserimento in mappa
        if clipped_layer.isValid():
            QgsProject.instance().addMapLayer(clipped_layer)
        else:
            print("Errore: Il layer GDI ritagliato risulta danneggiato o invalido.")

