    def calcola_mediaSlope(self):
        # Ottieni il layer vettoriale del poligono
        selected_poligon_layer_name = self.dlg.comboBox_15.currentText()
        poligono_layers = QgsProject.instance().mapLayersByName(selected_poligon_layer_name)
        
        if not poligono_layers:
            return
        
        poligono_layer = poligono_layers[0]

        slope_layers = QgsProject.instance().mapLayersByName('Pendenza')
        slope_layer = slope_layers[0]
        
        # Ottieni l'estensione del layer "Poligono"
        extent = poligono_layer.extent()
        extent_str = f"{extent.xMinimum()},{extent.xMaximum()},{extent.yMinimum()},{extent.yMaximum()} [EPSG:{poligono_layer.crs().postgisSrid()}]"

        result = processing.run("native:rastercalc", {
            'LAYERS' : [slope_layer],
            'EXPRESSION': '"Pendenza@1"',
            'EXTENT': extent_str,
            'CELL_SIZE': None,
            'CRS': None,
            'OUTPUT': 'TEMPORARY_OUTPUT'
        })
        raster_file = result['OUTPUT']
        raster_layer = QgsRasterLayer(raster_file, "Slope_ritagliato")
        QgsProject.instance().addMapLayer(raster_layer)

        result = processing.run("native:pixelstopoints", {
            'INPUT_RASTER': raster_layer,
            'RASTER_BAND': 1,
            'FIELD_NAME': 'SLOPE',
            'OUTPUT':'TEMPORARY_OUTPUT'
        })
        vector_layer = result['OUTPUT']
        QgsProject.instance().addMapLayer(vector_layer)
        vector_layer.setName("Slope_puntuale")

        parameters = {
                'INPUT': vector_layer,
                'PREDICATE': [0],  # Intersezione
                'INTERSECT': poligono_layer,
                'METHOD': 0
            }
        result = processing.run("native:selectbylocation", parameters)
        selected_features = vector_layer.selectedFeatures()

        # Crea un nuovo layer temporaneo con le feature selezionate
        temp_layer = QgsVectorLayer("Point?crs=" + vector_layer.crs().authid(), "temporary_points", "memory")
        temp_layer_data = temp_layer.dataProvider()
        attr = vector_layer.dataProvider().fields().toList()
        temp_layer_data.addAttributes(attr)
        temp_layer.updateFields()
        temp_layer_data.addFeatures(selected_features)

        # Aggiungi il nuovo layer temporaneo al progetto
        QgsProject.instance().addMapLayer(temp_layer)

        # Rimuovi la selezione dal layer di punti
        vector_layer.removeSelection()

        result = processing.run("qgis:basicstatisticsforfields",{
            'INPUT_LAYER':temp_layer,
            'FIELD_NAME':'SLOPE',
            'OUTPUT_HTML_FILE':'TEMPORARY_OUTPUT'})

        # Leggi il percorso del file HTML temporaneo
        html_file = result['OUTPUT_HTML_FILE']

        # Apre il file HTML e legge il contenuto
        with open(html_file, 'r', encoding='utf-8') as file:
            html_content = file.read()

        match = re.search(r"Mean value: ([\d.]+)", html_content)
        slope_arithmetic_mean = float(match.group(1))

        aspect_layers = QgsProject.instance().mapLayersByName('Esposizione')
        aspect_layer = aspect_layers[0]
        result = processing.run("native:rastercalc", {
            'LAYERS' : [aspect_layer],
            'EXPRESSION': '"Esposizione@1"',
            'EXTENT': extent_str,
            'CELL_SIZE': None,
            'CRS': None,
            'OUTPUT': 'TEMPORARY_OUTPUT'
        })
        raster_file = result['OUTPUT']
        raster_layer = QgsRasterLayer(raster_file, "Aspect_ritagliato")
        QgsProject.instance().addMapLayer(raster_layer)

        result = processing.run("native:pixelstopoints", {
            'INPUT_RASTER': raster_layer,
            'RASTER_BAND': 1,
            'FIELD_NAME': 'ASPECT',
            'OUTPUT':'TEMPORARY_OUTPUT'
        })
        vector_layer = result['OUTPUT']
        QgsProject.instance().addMapLayer(vector_layer)
        vector_layer.setName("Aspect_puntuale")

        parameters = {
                'INPUT': vector_layer,
                'PREDICATE': [0],  # Intersezione
                'INTERSECT': poligono_layer,
                'METHOD': 0
            }
        result = processing.run("native:selectbylocation", parameters)
        selected_features = vector_layer.selectedFeatures()

        # Crea un nuovo layer temporaneo con le feature selezionate
        temp_layer = QgsVectorLayer("Point?crs=" + vector_layer.crs().authid(), "temporary_points", "memory")
        temp_layer_data = temp_layer.dataProvider()
        attr = vector_layer.dataProvider().fields().toList()
        temp_layer_data.addAttributes(attr)
        temp_layer.updateFields()
        temp_layer_data.addFeatures(selected_features)

        # Aggiungi il nuovo layer temporaneo al progetto
        QgsProject.instance().addMapLayer(temp_layer)

        # Rimuovi la selezione dal layer di punti
        vector_layer.removeSelection()

        result = processing.run("qgis:basicstatisticsforfields",{
            'INPUT_LAYER':temp_layer,
            'FIELD_NAME':'ASPECT',
            'OUTPUT_HTML_FILE':'TEMPORARY_OUTPUT'})

        # Leggi il percorso del file HTML temporaneo
        html_file = result['OUTPUT_HTML_FILE']

        # Apre il file HTML e legge il contenuto
        with open(html_file, 'r', encoding='utf-8') as file:
            html_content = file.read()

        match = re.search(r"Mean value: ([\d.]+)", html_content)
        aspect_arithmetic_mean = float(match.group(1))

        slope_rad = math.radians(float(slope_arithmetic_mean))
        aspect_rad = math.radians(float(aspect_arithmetic_mean))
        if not self.dlg.lineEdit_4.text() or not self.dlg.lineEdit_8.text() or self.dlg.comboBox_5.currentIndex() == -1:
                        self.iface.messageBar().pushMessage("Valori di INC o LOS mancanti.", level=Qgis.Critical)
        else:
            los_az_ang_rad = math.radians(float(self.dlg.lineEdit_4.text()))
            inc_ang_rad = math.radians(float(self.dlg.lineEdit_8.text()))
            # Calcola L2A
            l2a_value = (los_az_ang_rad - math.radians(180) + math.radians(90)) - aspect_rad
                        
            # Calcola SLOPE2LOS
            slope2los_value = (math.sin(slope_rad)*math.cos(inc_ang_rad))+((math.cos(slope_rad)*math.sin(inc_ang_rad)*math.cos(l2a_value)))

            # Crea un layer temporaneo con gli stessi dati del layer originale
            layer_density = QgsVectorLayer("Polygon?crs={}".format(poligono_layer.crs().authid()), 
                                poligono_layer.name() + "_density", "memory")

            # Copia i campi e le features dal layer originale al layer temporaneo
            layer_density_data_provider = layer_density.dataProvider()
            layer_density_data_provider.addAttributes(poligono_layer.fields())
            layer_density.updateFields()

            for feature in poligono_layer.getFeatures():
                layer_density_data_provider.addFeature(feature)

            # Aggiungi il layer temporaneo al progetto
            QgsProject.instance().addMapLayer(layer_density)
            
            layer_density.startEditing()
            layer_density.dataProvider().addAttributes([QgsField('SLOPE2LOS', QVariant.Double)])
            layer_density.updateFields()
            layer_density.setName("Slope2LOS")
            idx_density = layer_density.fields().indexFromName('SLOPE2LOS')

            for feature in layer_density.getFeatures():
                layer_density.changeAttributeValue(feature.id(), int(idx_density), slope2los_value)
            layer_density.updateFields()
            layer_density.commitChanges()

