    def calcola_pendenza(self):
        # Ottieni il nome del layer raster selezionato
        selected_raster_layer_name = self.dlg.comboBox_2.currentText()

        # Ottieni il layer raster utilizzando il nome
        raster_layers = QgsProject.instance().mapLayersByName(selected_raster_layer_name)
        if raster_layers:
            selected_raster_layer = raster_layers[0]
        else:
            # Se non viene trovato alcun layer con il nome specificato
            self.iface.messageBar().pushMessage("Error: No raster layer found with the specified name.", level=Qgis.Warning)
            return
    
        # Verifica se il layer raster è valido
        if selected_raster_layer is None or not selected_raster_layer.isValid() or selected_raster_layer.type() != QgsMapLayer.RasterLayer:
            self.iface.messageBar().pushMessage("Error: No valid raster layer selected.", level=Qgis.Warning)
            return
    
        # Ottieni il percorso del layer raster selezionato
        selected_raster_layer_path = selected_raster_layer.source()

         # Imposta i parametri per l'algoritmo "native:slope"
        parameters = {
            'INPUT': selected_raster_layer_path,
            'Z_FACTOR': 1,
            'OUTPUT': 'TEMPORARY_OUTPUT'
        }

        # Esegui l'algoritmo "native:slope" utilizzando processing
        feedback = _ResponsiveFeedback(self.iface, "Pendenza")
        slope_algorithm = 'native:slope'
        result = processing.run(slope_algorithm, parameters, feedback=feedback)

        # Verifica se il processo è stato completato con successo
        if result and 'OUTPUT' in result:
        # Ottieni il percorso del layer risultante
            slope_layer_path = result['OUTPUT']
        
            # Carica il layer raster risultante nella mappa
            slope_layer = QgsRasterLayer(slope_layer_path, "Pendenza")
            QgsProject.instance().addMapLayer(slope_layer)
            # Nascondi il layer "Pendenza" utilizzando QgsLayerTree
            slope_layer_tree_node = QgsProject.instance().layerTreeRoot().findLayer(slope_layer.id())
            if slope_layer_tree_node:
                slope_layer_tree_node.setItemVisibilityChecked(False)
        else:
            self.iface.messageBar().pushMessage("An error occurred while calculating the slope.", level=Qgis.Critical)

