        aspect_algorithm = 'native:aspect'
        result = processing.run(aspect_algorithm, parameters, feedback=feedback)

        # Verifica se il processo è stato completato con successo
        if result and 'OUTPUT' in result:
            # Ottieni il percorso del layer risultante
            aspect_layer_path = result['OUTPUT']
        
            # Carica il layer raster risultante nella mappa
            aspect_layer = QgsRasterLayer(aspect_layer_path, "Esposizione")
            QgsProject.instance().addMapLayer(aspect_layer)

            # Nascondi il layer "Esposizione" utilizzando QgsLayerTree
            aspect_layer_tree_node = QgsProject.instance().layerTreeRoot().findLayer(aspect_layer.id())
            if aspect_layer_tree_node:
                aspect_layer_tree_node.setItemVisibilityChecked(False)
        else:
            self.iface.messageBar().pushMessage("An error occurred while calculating the aspect.", level=Qgis.Critical)
    
