    def estrai_valore_pixel_esposizione(self):
        """Estrai i valori del pixel raster per ogni elemento puntuale nel layer vettoriale selezionato."""
         # Trova il layer raster "Esposizione" per nome
        raster_layers = QgsProject.instance().mapLayersByName('Esposizione')
        if raster_layers:
            selected_raster_layer = raster_layers[0]
        else:
            # Se non viene trovato alcun layer con il nome specificato
            self.iface.messageBar().pushMessage("Error: No Aspect layer found.", level=Qgis.Warning)
            return

        # Ottieni il layer vettoriale utilizzando il nome
        vector_layers = QgsProject.instance().mapLayersByName('conSLOPE')
        if vector_layers:
            selected_vector_layer = vector_layers[0]
        else:
            # Se non viene trovato alcun layer con il nome specificato
            self.iface.messageBar().pushMessage("Error: No vector layer found with the specified name.", level=Qgis.Warning)
            return

        # Imposta i parametri per il comando di campionamento raster
        parameters = {
            'INPUT': selected_vector_layer.source(),
            'RASTERCOPY': selected_raster_layer.source(),
            'COLUMN_PREFIX': 'ASPECT',
            'OUTPUT': 'TEMPORARY_OUTPUT'
        }
        feedback = _ResponsiveFeedback()
        result = processing.run("native:rastersampling", parameters, feedback=feedback)
        
        # Ottieni il percorso del layer risultante
        new_layer2 = result['OUTPUT']
        QgsProject.instance().addMapLayer(new_layer2)
        new_layer2.setName('conEntrambi')

        new_layer2.startEditing()
        if 'SLOPE' in new_layer2.fields().names():
            slope_idx = new_layer2.fields().indexFromName('SLOPE')
            new_layer2.deleteAttribute(slope_idx)

        if 'ASPECT' in new_layer2.fields().names():
            aspect_idx = new_layer2.fields().indexFromName('ASPECT')
            new_layer2.deleteAttribute(aspect_idx)

        for field in new_layer2.fields():
            if field.name() == 'SLOPE1':
                    idx = new_layer2.fields().indexFromName(field.name())
                    new_layer2.renameAttribute(idx, 'SLOPE')
        for field in new_layer2.fields():
            if field.name() == 'ASPECT1':
                    idx = new_layer2.fields().indexFromName(field.name())
                    new_layer2.renameAttribute(idx, 'ASPECT')
        slope_idx = new_layer2.fields().indexFromName('SLOPE')
        # --- BULK: raccoglie tutti gli ID da eliminare, poi cancella in una sola chiamata ---
        fids_to_delete = {f.id() for f in new_layer2.getFeatures() if f.attributes()[slope_idx] == 0}
        if fids_to_delete:
            new_layer2.dataProvider().deleteFeatures(list(fids_to_delete))
        new_layer2.commitChanges()

