    def pulizia_layer(self, layer_names):
        # Rimuovi i layer specificati
        project = QgsProject.instance()
        for layer_name in layer_names:
            layers = project.mapLayersByName(layer_name)
            for layer in layers:
                project.removeMapLayer(layer)
    
    def calcola_RIndex2010(self):

        # Ottieni il layer vettoriale utilizzando il nome
        selected_vector_layer_name = "conEntrambi"
        vector_layers = QgsProject.instance().mapLayersByName(selected_vector_layer_name)
        if vector_layers:
            selected_vector_layer = vector_layers[0]
        else:
            # Se non viene trovato alcun layer con il nome specificato
            self.iface.messageBar().pushMessage("Errore: Nessun layer vettoriale trovato con il nome specificato.", level=Qgis.Warning)
            return

        # Ottieni il nome dell'attributo selezionato nella comboBox_3 e nella comboBox_4
        name_inc_ang = self.dlg.comboBox_3.currentText()
        name_los_az_ang = self.dlg.comboBox_4.currentText()

        # Ottieni gli indici dei campi degli attributi selezionati
        idx_slope = selected_vector_layer.fields().indexFromName('SLOPE')
        idx_aspect = selected_vector_layer.fields().indexFromName('ASPECT')
        idx_inc = selected_vector_layer.fields().indexFromName(name_inc_ang)
        idx_los = selected_vector_layer.fields().indexFromName(name_los_az_ang)

        #Choose the layer   
        new_layer = selected_vector_layer.clone()
        new_layer.setName("RIndex")
        QgsProject.instance().addMapLayer(new_layer)

        # Aggiungi colonna r_index
        new_layer.startEditing()
        new_layer.dataProvider().addAttributes([QgsField('RINDEX', QVariant.Double)])
        new_layer.updateFields()
        idx_rindex = new_layer.fields().indexFromName('RINDEX')
                                                      
        # Cicla attraverso le feature per ottenere il valore di INC e LOS dall'attributo selezionato
        for feature in new_layer.getFeatures():
            # Ottieni il valore di INC e LOS dall'attributo selezionato per la feature corrente
            SLOPE = feature[idx_slope]
            ASPECT = feature[idx_aspect]
           

            # Verifica se la lineEdit non è vuota
            if self.dlg.lineEdit.text():
                # Se la lineEdit non è vuota, usa il valore inserito manualmente
                LOS = self.dlg.lineEdit.text()
            else:
                # Altrimenti, usa il valore dall'attributo selezionato nella comboBox_4
                LOS = feature[idx_los]
            
            # Verifica se la lineEdit non è vuota
            if self.dlg.lineEdit_10.text():
                # Se la lineEdit non è vuota, usa il valore inserito manualmente
                INC = self.dlg.lineEdit_10.text()
            else:
                # Altrimenti, usa il valore dall'attributo selezionato nella comboBox_4
                INC = feature[idx_inc]

            # Converti gli angoli in radianti
            slope_rad = math.radians(float(SLOPE))
            aspect_rad = math.radians(float(ASPECT))
            inc_ang_rad = math.radians(float(INC))
            los_az_ang_rad = math.radians(float(LOS))

            # Calcola l'rindex
            r_index = math.sin(inc_ang_rad + math.atan(math.tan(slope_rad) * math.cos((los_az_ang_rad - math.radians(180) + math.radians (90))- aspect_rad)))

            new_layer.changeAttributeValue(feature.id(), int(idx_rindex), r_index)
            new_layer.updateFields()
        new_layer.commitChanges()

        #Stampa messaggio di successo
        self.iface.messageBar().pushMessage("R-Index calcolato con successo.", level=Qgis.Success)

