    def calcolaLOS_2(self):
        params = self.saved_parameters
        H_Sn = params['H_Sn']
        orb_inclination = params['orb_inclination']
        k = params['k']
        pass_mode = params['pass_mode']
        orb_inclination_rad = math.radians(orb_inclination)

        selected_vector_layer = QgsProject.instance().mapLayersByName("conEntrambi")[0]

        # Aggiunta del campo temp_los direttamente nel layer
        if selected_vector_layer.fields().indexFromName('temp_los') == -1:
            selected_vector_layer.dataProvider().addAttributes([QgsField('temp_los', QVariant.Double, 'double')])
            selected_vector_layer.updateFields()

        idx_los = selected_vector_layer.fields().indexFromName('temp_los')

        line_edit_val = self.dlg.lineEdit_16.text()
        combo_text = self.dlg.comboBox_15.currentText()

        # Pre-calcola l'indice del campo INC (fisso per tutte le feature)
        idx_inc = selected_vector_layer.fields().indexFromName(combo_text) if line_edit_val == '' else -1
        fixed_inc_rad = math.radians(float(line_edit_val)) if line_edit_val != '' else None

        # --- BULK: raccoglie tutti i valori e scrive in un'unica operazione I/O ---
        changes = {}
        for feature in selected_vector_layer.getFeatures():
            point = feature.geometry().asPoint()
            Lat_m_rad = math.radians(point.y())

            inc_ang_m_rad = fixed_inc_rad if fixed_inc_rad is not None else math.radians(float(feature.attribute(idx_inc)))

            denom = math.cos(Lat_m_rad)**2 - math.cos(orb_inclination_rad)**2
            if denom < 0:
                self.iface.messageBar().pushMessage("Valore sotto radice negativo nel calcolo LOS.", level=Qgis.Critical)
                return

            heading_S = math.degrees(math.atan((math.cos(orb_inclination_rad) - (math.cos(Lat_m_rad) ** 2) / k) / math.sqrt(denom)))
            if pass_mode == "DESC":
                heading_S = 180 - heading_S

            dheading = (H_Sn / 6371000) * math.tan(inc_ang_m_rad) * math.cos(math.radians(heading_S)) * math.tan(Lat_m_rad)
            heading_angle = (heading_S + dheading - 180) % 360
            if heading_angle < 0:
                heading_angle += 360

            changes[feature.id()] = {idx_los: heading_angle}

        # Unica scrittura bulk al dataProvider
        selected_vector_layer.dataProvider().changeAttributeValues(changes)
        selected_vector_layer.updateFields()
        
    def calcolaLOS_3(self):
        # Recupero parametri dalla formattazione
        params = self.saved_parameters
        H_Sn = params['H_Sn']
        orb_inclination = params['orb_inclination']
        k = params['k']
        pass_mode = params['pass_mode']
        orb_inclination_rad = math.radians(orb_inclination)

        # Ottieni il layer vettoriale utilizzando il nome
        selected_vector_layer_name = "conEntrambi"
        vector_layers = QgsProject.instance().mapLayersByName(selected_vector_layer_name)
        if vector_layers:
            selected_vector_layer = vector_layers[0]
        else:
            self.iface.messageBar().pushMessage("Error: No vector layer found with the specified name.", level=Qgis.Warning)
            return

        # Aggiunta del campo temp_los direttamente nel layer (solo se non esiste già)
        if selected_vector_layer.fields().indexFromName('temp_los') == -1:
            selected_vector_layer.dataProvider().addAttributes([QgsField('temp_los', QVariant.Double, 'double')])
            selected_vector_layer.updateFields()

        idx_los = selected_vector_layer.fields().indexFromName('temp_los')

        # Pre-calcola indice INC e valore fisso fuori dal loop
        line_edit_val = self.dlg.lineEdit_21.text()
        combo_text = self.dlg.comboBox_23.currentText()
        idx_inc = selected_vector_layer.fields().indexFromName(combo_text) if line_edit_val == '' else -1
        fixed_inc_rad = math.radians(float(line_edit_val)) if line_edit_val != '' else None

        # --- BULK: raccoglie tutti i valori e scrive in un'unica operazione I/O ---
        changes = {}
        for feature in selected_vector_layer.getFeatures():
            point = feature.geometry().asPoint()
            Lat_m_rad = math.radians(point.y())

            inc_ang_m_rad = fixed_inc_rad if fixed_inc_rad is not None else math.radians(float(feature.attribute(idx_inc)))

            denom = math.cos(Lat_m_rad)**2 - math.cos(orb_inclination_rad)**2
            if denom < 0:
                self.iface.messageBar().pushMessage("Calculation error: the value under the square root is negative.", level=Qgis.Critical)
                return

            # Calcolo di heading ang
            heading_S = math.degrees(math.atan((math.cos(orb_inclination_rad) - (math.cos(Lat_m_rad) ** 2) / k) /
                            math.sqrt(denom)))

            # Modifica se la modalità è discendente
            if pass_mode == "DESC":
                heading_S = 180 - heading_S

            # Calcolo di dheading
            dheading = (H_Sn / 6371000) * math.tan(inc_ang_m_rad) * math.cos(math.radians(heading_S)) * math.tan(Lat_m_rad)

            # Calcolo di heading_angle con normalizzazione corretta
            heading_angle = ((heading_S + dheading) - 180) % 360
            if heading_angle < 0:
                heading_angle += 360

            changes[feature.id()] = {idx_los: heading_angle}

        # Unica scrittura bulk al dataProvider
        selected_vector_layer.dataProvider().changeAttributeValues(changes)
        selected_vector_layer.updateFields()

    def calcolaLOS5(self):
        params = self.saved_parameters
        H_Sn = params['H_Sn']
        orb_inclination = params['orb_inclination']
        k = params['k']
        pass_mode = params['pass_mode']

        if self.dlg.comboBox_11.currentText() != '':
            #da geotiff inc_ang
            # Recupero parametri dalla formattazione
            orb_inclination_rad = math.radians(orb_inclination)
            
            # Calcolo lat media da geotiff inc_ang
            raster_layer = QgsProject.instance().mapLayersByName(self.dlg.comboBox_11.currentText())[0]
            extent = raster_layer.extent()
            Lat_m = (extent.yMinimum() + extent.yMaximum()) / 2
            Lat_m_rad = math.radians(Lat_m)

            # Calcolo inc medio da geotiff
            stats = raster_layer.dataProvider().bandStatistics(1, QgsRasterBandStats.All)
            inc_ang_m = stats.mean
            inc_ang_m_rad = math.radians(inc_ang_m)

                # controlli aggiunti per errore prof
            denom = math.cos(Lat_m_rad)**2 - math.cos(orb_inclination_rad)**2
            if denom < 0:
                self.iface.messageBar().pushMessage("Error during calculation: the value under the square root is negative.", level=Qgis.Critical)
                return

            # Calcolo di heading ang
            heading_S = math.degrees(math.atan((math.cos(orb_inclination_rad) - (math.cos(Lat_m_rad) ** 2) / k) / 
                                math.sqrt(math.cos(Lat_m_rad) ** 2 - math.cos(orb_inclination_rad) ** 2)))

            # Modifica se la modalità è discendente
            if pass_mode == "DESC":
                heading_S = 180 - heading_S

            # Calcolo di dheading
            Re = 6371000
            dheading = (H_Sn / Re) * math.tan(inc_ang_m_rad) * math.cos(math.radians(heading_S)) * math.tan(Lat_m_rad)

            # Calcolo di heading_angle
            head_nonnormalized = (heading_S + dheading) - 180
            self.heading_angle = head_nonnormalized % 360
            if self.heading_angle < 0:
                self.heading_angle += 360
                return self.heading_angle
            
        elif self.dlg.comboBox_9.currentText() != '':
            #da dem
            # Recupero parametri dalla formattazione
            orb_inclination_rad = math.radians(orb_inclination)
            
            # Calcolo lat media da dem
            raster_layer = QgsProject.instance().mapLayersByName(self.dlg.comboBox_9.currentText())[0]
            extent = raster_layer.extent()
            Lat_m = (extent.yMinimum() + extent.yMaximum()) / 2
            Lat_m_rad = math.radians(Lat_m)

            # Calcolo inc medio da valore manuale
            inc_ang_m = float(self.dlg.lineEdit_10.text())
            inc_ang_m_rad = math.radians(inc_ang_m)

            # controlli aggiunti per errore prof
            denom = math.cos(Lat_m_rad)**2 - math.cos(orb_inclination_rad)**2
            if denom < 0:
                self.iface.messageBar().pushMessage("Error during calculation: the value under the square root is negative.", level=Qgis.Critical)
                return

            # Calcolo di heading ang
            heading_S = math.degrees(math.atan((math.cos(orb_inclination_rad) - (math.cos(Lat_m_rad) ** 2) / k) / 
                            math.sqrt(math.cos(Lat_m_rad) ** 2 - math.cos(orb_inclination_rad) ** 2)))

            # Modifica se la modalità è discendente
            if pass_mode == "DESC":
                heading_S = 180 - heading_S

            # Calcolo di dheading
            Re = 6371000
            dheading = (H_Sn / Re) * math.tan(inc_ang_m_rad) * math.cos(math.radians(heading_S)) * math.tan(Lat_m_rad)

            # Calcolo di heading_angle
            head_nonnormalized = (heading_S + dheading) - 180
            self.heading_angle = head_nonnormalized % 360
            if self.heading_angle < 0:
                self.heading_angle += 360
                return self.heading_angle
        else:
            self.iface.messageBar().pushMessage("All formatting fields must be filled!", level=Qgis.Critical)
            self.errore = 1.

