    def addRaster1(self):
        # Ottieni il nome del layer raster selezionato
        selected_raster_layer_name = self.dlg.comboBox_9.currentText()

        # Ottieni il layer raster utilizzando il nome
        raster_layers = QgsProject.instance().mapLayersByName(selected_raster_layer_name)

        raster_layer = raster_layers[0]
        # Ottieni l'estensione del layer "Aspect"
        extent = raster_layer.extent()
        extent_str = f"{extent.xMinimum()},{extent.xMaximum()},{extent.yMinimum()},{extent.yMaximum()} [EPSG:{raster_layer.crs().postgisSrid()}]"
        if self.dlg.comboBox_11.currentText() == '':
            if not self.dlg.lineEdit_10.text():
                self.iface.messageBar().pushMessage("Missing INC value.", level=Qgis.Critical)
            else:
                manual_inc = float(self.dlg.lineEdit_10.text())

            params = {
                'EXTENT': extent_str,
                'TARGET_CRS': raster_layer.crs(),  # CRS di destinazione
                'PIXEL_SIZE': 10,  # Dimensione del pixel
                'NUMBER': manual_inc,  # Valore costante per ogni pixel
                'OUTPUT_TYPE': 5,  # Tipo di output (Float32)
                'OUTPUT': 'TEMPORARY_OUTPUT'  # Output temporaneo
            }   
            # Esegui l'algoritmo
            result = processing.run("native:createconstantrasterlayer", params)

            # Ottieni il layer raster temporaneo
            raster_file = result['OUTPUT']
            raster_layer = QgsRasterLayer(raster_file, "Temp INC")
            QgsProject.instance().addMapLayer(raster_layer)

            manual_los = self.heading_angle
            params = {
                'EXTENT': extent_str,
                'TARGET_CRS': raster_layer.crs(),  # CRS di destinazione
                'PIXEL_SIZE': 10,  # Dimensione del pixel
                'NUMBER': manual_los,  # Valore costante per ogni pixel
                'OUTPUT_TYPE': 5,  # Tipo di output (Float32)
                'OUTPUT': 'TEMPORARY_OUTPUT'  # Output temporaneo
            }
            # Esegui l'algoritmo
