    def calculate_statistics_for_all_features(self):
        """
        Launcher per il calcolo statistico su tutte le feature.
        Esegue la validazione dei parametri nel thread principale, poi
        delega il calcolo pesante a StatisticsWorker in un QThread separato
        per non bloccare la GUI di QGIS.
        """
        self.canvas = self.iface.mapCanvas()

        # ── Validazioni nel thread principale ────────────────────────────────
        selected_layer_name = self.dlg.comboBox_28.currentText()
        if not selected_layer_name:
            QMessageBox.warning(None, "No layer selected", "Please select a valid layer.")
            return

        selected_layer = next((l for l in QgsProject.instance().mapLayers().values() if l.name() == selected_layer_name), None)
        if not selected_layer:
            QMessageBox.warning(None, "Layer not found", f"The layer '{selected_layer_name}' was not found.")
            return

        s = self.dlg.comboBox_datelayer.currentText()
        if not s:
            QMessageBox.warning(None, "No date selected", "Please select a valid date.")
            return

        user_format = self.dlg.comboBox_date.currentText()
        if not user_format:
            QMessageBox.warning(None, "No date format selected", "Please select a valid format.")
            return

        format_map = {
            "dd/MM/yyyy": "%d/%m/%Y",
            "MM/dd/yyyy": "%m/%d/%Y",
            "yyyy-MM-dd": "%Y-%m-%d",
            "ddMMyyyy": "%d%m%Y",
            "yyyyMMdd": "%Y%m%d"
        }
        fmt = format_map.get(user_format)

        def is_field_date(field_name):
            solo_numeri = re.sub(r'\D', '', field_name)
            if len(solo_numeri) != 8:
                return False
            try:
                datetime.strptime(solo_numeri, fmt)
                return True
            except:
                return False

        date_fields = [f.name() for f in selected_layer.fields() if is_field_date(f.name())]
        if not date_fields:
            QMessageBox.information(None, "No date field", "No date-formatted field found in the layer.")
            return

        def extract_date_from_fieldname(field_name):
            numeri = re.sub(r'\D', '', field_name)
            return datetime.strptime(numeri, fmt)

        fields_sorted = sorted(date_fields, key=extract_date_from_fieldname)
        dates_dt = [extract_date_from_fieldname(f) for f in fields_sorted]
        dates_np = np.array([np.datetime64(d.date()) for d in dates_dt])
        t = (dates_np - dates_np[0]).astype('timedelta64[D]').astype(int)

        if self.dlg.lineEdit_18.text():
            lambda_ = float(self.dlg.lineEdit_18.text())
        else:
            params = self.saved_parameters
            lambda_ = params['lambda_set']

        # ── Progress dialog ───────────────────────────────────────────────────
        self._stats_layer_name = selected_layer_name
        self._stats_progress = QProgressDialog(
            "Starting statistics calculation...", "Cancel", 0, 100,
            self.iface.mainWindow()
        )
        self._stats_progress.setWindowTitle("Statistics Calculation")
        self._stats_progress.setMinimumWidth(450)
        self._stats_progress.setWindowModality(0)
        self._stats_progress.setMinimumDuration(0)
        self._stats_progress.setValue(0)
        self._stats_progress.show()
        QApplication.processEvents()

        # ── Avvio worker in QThread ───────────────────────────────────────────
        self._stats_thread = QThread()
        self._stats_worker = StatisticsWorker(selected_layer, fields_sorted, t, lambda_, self)
        self._stats_worker.moveToThread(self._stats_thread)

        self._stats_thread.started.connect(self._stats_worker.run)
        self._stats_worker.progress.connect(self._on_stats_progress)
        self._stats_worker.finished.connect(self._on_stats_finished)
        self._stats_worker.error.connect(self._on_stats_error)
        self._stats_progress.canceled.connect(self._stats_worker.cancel)

        self.main_menu.pushButton_NLDT.setEnabled(False)
        self._stats_thread.start()

    def _on_stats_progress(self, value, label):
        if self._stats_progress:
            self._stats_progress.setValue(value)
            self._stats_progress.setLabelText(label)
        QApplication.processEvents()

    def _on_stats_finished(self, clone_layer):
        """Chiamato dal thread principale quando il worker ha terminato."""
        self._stats_thread.quit()
        self._stats_thread.wait()

        if self._stats_progress:
            self._stats_progress.setValue(100)
            self._stats_progress.close()

        self.main_menu.pushButton_NLDT.setEnabled(True)

        original_name = self._stats_layer_name
        clone_layer.setName(f"{original_name}_TM")
        clone_layer.updateFields()
        QgsProject.instance().addMapLayer(clone_layer)

        self.iface.messageBar().pushMessage(
            "Completed",
            "Calculation of statistical indices completed for all features.",
            level=Qgis.Success
        )

    def _on_stats_error(self, msg):
        self._stats_thread.quit()
        self._stats_thread.wait()
        if self._stats_progress:
            self._stats_progress.close()
        self.main_menu.pushButton_NLDT.setEnabled(True)
        self.iface.messageBar().pushMessage(
            "Error",
            f"Error during statistics calculation: {msg}",
            level=Qgis.Critical
        )